    "faqRows": {
      "label": "FAQ rows",
      "group": "Exact",
      "html": "\n\n            <!-- BLOCK: FAQ rows -->\n            <tr>\n              <td class=\"mobile-pad\" style=\"padding:0 32px 42px 32px;background-color:#ffffff;\">\n                <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"background-color:#e5e1e0;border-radius:24px;border-collapse:separate !important;box-shadow:0 10px 30px #f1eeee;\">\n                  <tr>\n                    <td style=\"padding:1px;\"><table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"background-color:#ffffff;border-radius:23px;border-collapse:separate !important;\"><tr><td style=\"padding:24px;\">\n                      <h2 class=\"section-title\" style=\"margin:0 0 18px 0;font-family:Georgia,Cambria,'Times New Roman',Times,serif;letter-spacing:-0.02em;font-size:32px;line-height:35px;font-weight:bold;color:#363635;\">Investing FAQs</h2>\n                      <table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\n                        <tr>\n                          <td style=\"padding:0 0 18px 0;border-bottom:1px solid #e9e4e3;\">\n                            <h3 style=\"margin:0 0 8px 0;font-family:Georgia,Cambria,'Times New Roman',Times,serif;letter-spacing:-0.02em;font-size:22px;line-height:25px;font-weight:bold;color:#363635;\">Can I sell early?</h3>\n                            <p style=\"margin:0;font-family:Arial,sans-serif;letter-spacing:0.005em;font-size:15px;line-height:23px;color:#4d4a46;\">We operate a marketplace where you can list your investment for sale before the term ends, but selling is not guaranteed.</p>\n                          </td>\n                        </tr>\n                        <tr>\n                          <td style=\"padding:18px 0 0 0;\">\n                            <h3 style=\"margin:0 0 8px 0;font-family:Georgia,Cambria,'Times New Roman',Times,serif;letter-spacing:-0.02em;font-size:22px;line-height:25px;font-weight:bold;color:#363635;\">Are returns guaranteed?</h3>\n                            <p style=\"margin:0;font-family:Arial,sans-serif;letter-spacing:0.005em;font-size:15px;line-height:23px;color:#4d4a46;\">No. Capital is at risk and returns are not guaranteed. Always read the offer document before investing.</p>\n                          </td>\n                        </tr>\n                      </table>\n                    </td>\n                  </tr>\n                </table>\n                    </td>\n                  </tr>\n                </table>\n              </td>\n            </tr>"
    },
